const mobileOpen = ref(false) watch(() => route.path, () => { mobileOpen.value = false }) function logout() { authStore.logout(); router.push('/login') } function goHome() { router.push(authStore.user?.role === 'Evaluateur' ? '/evaluator/interviews' : '/dashboard')
} /* ── NAVIGATION ─────────────────────────────────────── */
