/convocations' }, { label: 'Émargement', icon: 'clipboard', href: '/emargement' }, { label: 'Candidatures', icon: 'clipboard', href: '/candidatures' }, if (['Evaluateur','Évaluateur'].includes(role)) return [ { label: 'Mes entretiens', icon: 'calendar', href: '/evaluator/interviews' }, { label: 'Mes candidats', icon: 'users', href: '/evaluator/candidates' }, return [{ label: 'Tableau de bord', icon: 'dashboard', href: '/dashboard' }]
}) /* ── ICONS ──────────────────────────────────────────── */
