ne"> <circle cx="12" cy="8" r="3.2" stroke="currentColor" stroke-width="1.7"/> <path d="M5.5 20c.8-4 2.9-6 6.5-6s5.7 2 6.5 6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/> </svg>`, sparkles: `<svg viewBox="0 0 24 24" fill="none"> <path d="M12 2L14.4 7.6L20 10L14.4 12.4L12 18L9.6 12.4L4 10L9.6 7.6L12 2Z" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/> <path d="M19 16L20.2 18.8L23 20L20.2 21.2L19 24L17.8 21.2L15 20L17.8 18.8L19 16Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/> </svg>`, logout: `<svg viewBox="0 0 24 24" fill="none"> <path d="M10 4H6.5A1.5 1.5 0 0 0 5 5.5v13A1.5 1.5 0 0 0 6.5 20H10" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/> <path d="M14 8l4 4-4 4M18 12H9" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/> </svg>`,
} function isActive(href) { if (href === '/dashboard') return route.path === '/dashboard' return route.path === href || route.path.startsWith(`${href}/`)
} const userInitials = computed(() => { const u = authStore.user if (!u) return 'U' if (u.prenom || u.nom) return `${u.prenom?.charAt(0) || ''}${u.nom?.charAt(0) || ''}`.toUpperCase() if (u.name) return u.name.split(' ').map(p => p.charAt(0)).join('').slice(0, 2).toUpperCase() return 'U'
}) const userName = computed(() => { const u = authStore.user if (!u) return 'Utilisateur' if (u.prenom || u.nom) return `${u.prenom || ''} ${u.nom || ''}`.trim() return u.name || u.role || 'Utilisateur'
}) const userRole = computed(() => authStore.user?.role || 'Utilisateur')
</script> <template> <!-- ── MOBILE TOGGLE ─────────────────────────────── --> <button type="button" class="fixed left-4 top-3.5 z-40 grid h-10 w-10 place-items-center rounded-xl bg-[#01313E] text-white lg:hidden transition-all duration-200 active:scale-95" aria-label="Ouvrir le menu" @click="mobileOpen = true" > <svg viewBox="0 0 20 20" fill="none" class="w-5 h-5"> <path d="M3 5h14M3 10h14M3 15h8" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/> </svg> </button> <!-- ── MOBILE OVERLAY ───────────────────────────── --> <Transition enter-active-class="transition duration-200" enter-="opacity-0" enter-="opacity-100" leave-active-class="transition duration-150" leave-="opacity-100" leave-="opacity-0" > <div v-if="mobileOpen" class="fixed inset-0 z-40 bg-[#01313E]/60 lg:hidden" @click="mobileOpen = false" /> </Transition> <!-- ── SIDEBAR ──────────────────────────────────── --> <aside class="fixed inset-y-0 left-0 z-50 w-[272px] flex flex-col bg-[#01313E] transition-transform duration-300 lg:translate-x-0" :class="mobileOpen ? 'translate-x-0' : '-translate-x-full'" > <!-- Background decoration --> <div class="pointer-events-none absolute inset-0 overflow-hidden"> <div class="absolute -top-24 -right-24 w-72 h-72 bg-[#E30046] rounded-full opacity-[.10]"></div> <div class="absolute -bottom-40 -left-24 w-96 h-96 bg-[#E30046] rounded-full opacity-[.05]"></div> <div class="absolute inset-0 opacity-[.03]" style="background-image: radial-gradient(circle, #ffffff 1px, transparent 1px); background-size: 18px 18px;"></div> </div> <div class="relative flex h-full flex-col"> <!-- ── LOGO ──────────────────────────────────── --> <div class="flex items-center justify-between px-4 py-4 border-b border-white/[.07]"> <button type="button" class="flex items-center group py-1" @click="goHome"> <img :src="logo" alt="Simplon Sourcing" class="h-9 w-auto object-contain transition-transform duration-200 group-hover:scale-105" /> </button> <button type="button" class="grid h-8 w-8 place-items-center rounded-lg text-white/40 hover:bg-white/10 hover:text-white transition lg:hidden" @click="mobileOpen = false" > <svg viewBox="0 0 20 20" fill="none" class="w-4 h-4"> <path d="M4 4l12 12M16 4L4 16" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/> </svg> </button> </div> <!-- ── USER CARD ─────────────────────────────── --> <div class="px-3 pt-4 pb-2"> <div class="rounded-2xl bg-white/[.07] border border-white/[.08] p-3"> <div class="flex items-center gap-3"> <div class="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[#E30046] text-sm font-black text-white"> {{ userInitials }} </div> <div class="min-w-0 flex-1"> <p class="truncate text-sm font-bold text-white leading-tight">{{ userName }}</p> <p class="truncate text-[11px] font-medium text-white/45 mt-0.5">{{ userRole }}</p> </div> </div> </div> </div> <!-- ── NAV LABEL ─────────────────────────────── --> <p class="px-5 pb-1.5 pt-4 text-[10px] font-black uppercase tracking-[.22em] text-[#E30046]"> Navigation </p> <!-- ── NAV LINKS ─────────────────────────────── --> <nav class="flex-1 overflow-y-auto px-3 pb-2 space-y-0.5 custom-scrollbar" aria-label="Navigation principale" > <RouterLink v-for="(item, i) in navigation" :key="item.href" :to="item.href" class="nav-link group flex items-center gap-3 w-full rounded-xl px-3 py-2.5 text-sm font-semibold transition-all duration-150" :class="isActive(item.href) ? 'bg-white text-[#01313E] font-bold' : 'text-white/65 hover:bg-white/[.09] hover:text-white'" :style="{ animationDelay: (i * 35) + 'ms' }" > <span class="grid h-8 w-8 shrink-0 place-items-center rounded-lg transition-all duration-150" :class="isActive(item.href) ? 'bg-[#E30046] text-white' : 'bg-white/[.07] text-white/55 group-hover:bg-white/[.14] group-hover:text-white'" v-html="icons[item.icon]" /> <span class="min-w-0 truncate flex-1">{{ item.label }}</span> <span v-if="isActive(item.href)" class="w-1.5 h-1.5 rounded-full bg-[#E30046] flex-shrink-0" /> </RouterLink> </nav> <!-- ── FOOTER ─────────────────────────────────── --> <div class="border-t border-white/[.07] px-3 py-3 space-y-0.5"> <button type="button" class="group flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-white/80 bg-white/[.05] border border-white/[.08] hover:bg-[#E30046]/20 hover:border-[#E30046]/40 hover:text-white transition" @click="() => { window.dispatchEvent(new CustomEvent('open-sourcingchat')); mobileOpen = false; }" > <span class="grid h-8 w-8 place-items-center rounded-lg bg-[#E30046] text-white transition" v-html="icons.sparkles" /> <div class="flex flex-col items-start min-w-0"> <span class="truncate font-bold">SourcingChat</span> <span class="text-[10px] text-emerald-400 font-normal">IA Connectée</span> </div> </button> <button type="button" class="group flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-white/60 hover:bg-white/[.09] hover:text-white transition" @click="router.push('/profil')" > <span class="grid h-8 w-8 place-items-center rounded-lg bg-white/[.07] text-white/55 group-hover:bg-white/[.14] group-hover:text-white transition" v-html="icons.user" /> <span>Mon profil</span> </button> <button type="button" class="group flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-white/55 hover:bg-[#E30046]/[.18] hover:text-[#E30046] transition" @click="logout" > <span class="grid h-8 w-8 place-items-center rounded-lg bg-white/[.07] text-white/55 transition group-hover:bg-[#E30046] group-hover:text-white" v-html="icons.logout" /> <span>Déconnexion</span> </button> </div> </div> </aside>
